def _face(family: str, weight: int, b64: str) -> str:
    return (f"@font-face{{font-family:'{family}';font-weight:{weight};font-style:normal;"
            f"font-display:swap;src:url(data:font/woff2;base64,{b64}) format('woff2');}}")


FONT_CSS = "".join(_face(f, w, b) for f, w, b in [("Fraunces", 400, _FRAUNCES_400), ("Fraunces", 600, _FRAUNCES_600), ("Geist", 400, _GEIST_400), ("Geist", 600, _GEIST_600), ("Geist Mono", 400, _GEIST_MONO_400)])
